        for item in messages {
            match item {
                Item::UserMessage { content } => {
                    self.events
                        .push(SessionEvent::user_message(content.clone()));
                }
                Item::AssistantMessage { content, agent } => {
                    let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
